package com.example.rokidgeminisecretary;
import android.content.*;import org.json.*;import java.io.*;
/** Review metadata; deadlines never silently delete or alter AI-visible memories. */
final class MemoryProvenance {
 static String fingerprint(JSONObject row)throws Exception{return ReviewStore.hash(new JSONObject().put("id",row.getString("id")).put("topic",row.getString("topic")).put("content",row.getString("content")).put("timestamp",row.getString("timestamp")));}
 static JSONObject current(Context c,String id)throws Exception{JSONArray rows=new DynamicMemorySync(c).state().getJSONArray("entries");for(int i=0;i<rows.length();i++)if(id.equals(rows.getJSONObject(i).getString("id")))return rows.getJSONObject(i);throw new IOException("記憶が未取得・削除済みです。既存の記憶画面から再取得してください");}
 static synchronized JSONArray list(Context c)throws Exception{JSONObject store=ReviewStore.read(c,"memory-provenance");JSONArray rows=new DynamicMemorySync(c).state().getJSONArray("entries"),out=new JSONArray();for(int i=0;i<Math.min(200,rows.length());i++){JSONObject row=rows.getJSONObject(i),item=new JSONObject(row.toString()).put("fingerprint",fingerprint(row));JSONObject meta=store.optJSONObject(row.getString("id"));if(meta!=null)item.put("provenance",new JSONObject(meta.toString()).put("matchesContent",meta.optString("fingerprint").equals(fingerprint(row))).put("reviewDue",meta.optLong("reviewAt")>0&&System.currentTimeMillis()>=meta.optLong("reviewAt")));JSONArray conflicts=new JSONArray();for(int j=0;j<rows.length();j++)if(i!=j&&RecordSearchPolicy.normalized(row.getString("topic")).equals(RecordSearchPolicy.normalized(rows.getJSONObject(j).getString("topic")))&&!row.getString("content").equals(rows.getJSONObject(j).getString("content")))conflicts.put(rows.getJSONObject(j).getString("id"));item.put("sameTopicDifferentContent",conflicts);out.put(item);}return out;}
 static synchronized JSONObject save(Context c,JSONObject input)throws Exception{String id=input.getString("id"),source=input.getString("source").trim();long review=input.optLong("reviewAt");if(!id.matches("[A-Za-z0-9_-]{1,100}")||source.length()>300||review<0||review>System.currentTimeMillis()+3660L*86400000)throw new IOException("出典・見直し期限を確認してください");JSONObject memory=current(c,id);if(!fingerprint(memory).equals(input.getString("fingerprint")))throw new IOException("記憶の本文が更新されています。開き直してください");JSONObject store=ReviewStore.read(c,"memory-provenance"),old=store.optJSONObject(id);int revision=old==null?0:old.optInt("revision");if(input.getInt("revision")!=revision)throw new IOException("出典が更新されています");if(old==null&&store.length()>=200)throw new IOException("出典記録は200件までです");JSONObject meta=new JSONObject().put("source",source).put("sourceKind","user-declared").put("reviewAt",review).put("fingerprint",fingerprint(memory)).put("recordedAt",System.currentTimeMillis()).put("revision",revision+1);store.put(id,meta);ReviewStore.write(c,"memory-provenance",store);return meta;}
 static void edit(Context c,JSONObject input)throws Exception{JSONObject row=current(c,input.getString("id"));if(!fingerprint(row).equals(input.getString("fingerprint")))throw new IOException("記憶が更新されています");new DynamicMemorySync(c).queue(row,"edit",input.getString("topic"),input.getString("content"));}
 private MemoryProvenance(){}
}
